# Destructible walls: per level, list of (room, x, y, w, h, dynamite_ok).
# Wall-breaking model (project decision 2026-07-10): DYNAMITE breaks walls,
# the laser is for enemies only. This intentionally diverges from the raw ROM
# capture (which showed the opening pillar melting under sustained laser fire)
# in favour of the classic, intuitive H.E.R.O. mechanic the game is built
# around: plant dynamite -> retreat -> blast a hole through.
# The blocking walls in levels 1-3 are:
#   * every level's opening-room central pillar (x60-67, y19-98) — the shaft
#     down to the next room sits behind it, so blasting it is the opening move;
#   * level 2 room 1's pillar foot (down to the floor band);
#   * nothing else in levels 1-3 is destructible.
# These walls stay baked in the background; the renderer stamps black over
# a wall once a blast has destroyed it.
DESTRUCTIBLE = [
    [(0, 60, 19, 8, 80, 1)],
    [(0, 60, 19, 8, 80, 1), (1, 52, 76, 8, 23, 1)],
    [(0, 60, 19, 8, 80, 1)],
]

